import numpy as np
from scipy import stats

def _ll(X, y, it=25):
    X = np.column_stack([np.ones(len(y)), X]) if X.size else np.ones((len(y), 1))
    b = np.zeros(X.shape[1])
    for _ in range(it):
        p = 1 / (1 + np.exp(-np.clip(X @ b, -30, 30)))
        w = p * (1 - p) + 1e-9
        H = X.T @ (X * w[:, None]) + 1e-6 * np.eye(X.shape[1])
        step = np.linalg.solve(H, X.T @ (y - p))
        b += step
        if np.abs(step).max() < 1e-8:
            break
    p = np.clip(1 / (1 + np.exp(-np.clip(X @ b, -30, 30))), 1e-12, 1 - 1e-12)
    return float(np.sum(y * np.log(p) + (1 - y) * np.log(1 - p)))

def design(feats):
    x, y, ids = np.asarray(feats.x, float), np.asarray(feats.y, float), list(feats.ids)
    n, p = x.shape
    labs = sorted(set(feats.stratum))
    S = np.column_stack([[s == l for s in feats.stratum] for l in labs[1:]]).astype(float) if len(labs) > 1 else np.zeros((n, 0))
    R = np.corrcoef(x, rowvar=False)
    def ll(cols, extra=None):
        M = [S, x[:, cols]] + ([extra] if extra is not None else [])
        return _ll(np.column_stack(M), y)
    sel, base = [], ll([])
    a1 = 0.05 / p
    while len(sel) < MAX_DRIVERS:
        best = None
        for j in range(p):
            if j in sel or any(abs(R[j, k]) >= 0.6 for k in sel):
                continue
            l = ll(sel + [j])
            if best is None or l > best[0]:
                best = (l, j)
        if best is None or stats.chi2.sf(2 * (best[0] - base), 1) > a1:
            break
        sel.append(best[1]); base = best[0]
    if not sel:
        # joint pair search for suppressed pairs (each weak alone)
        a2, best = 0.05 / (p * (p - 1) / 2), None
        for i in range(p):
            for j in range(i + 1, p):
                if abs(R[i, j]) >= 0.95:
                    continue
                l = ll([i, j])
                if best is None or l > best[0]:
                    best = (l, i, j)
        if best and stats.chi2.sf(2 * (best[0] - base), 2) < a2:
            sel = [best[1], best[2]]; base = best[0]
    changed = True
    while changed and len(sel) > 1:
        changed = False
        for j in list(sel):
            rest = [k for k in sel if k != j]
            if stats.chi2.sf(2 * (base - ll(rest)), 1) > a1:
                sel = rest; base = ll(sel); changed = True; break
    prods, a3, best = [], 0.01 / (p * (p - 1) / 2), None
    for i in range(p):
        for j in range(i + 1, p):
            if abs(R[i, j]) >= 0.6:
                continue
            cols = sorted(set(sel) | {i, j})
            l0 = ll(cols); l1 = ll(cols, x[:, i] * x[:, j])
            if best is None or l1 - l0 > best[0]:
                best = (l1 - l0, i, j)
    if best and stats.chi2.sf(2 * best[0], 1) < a3:
        i, j = best[1], best[2]
        prods = [(ids[i], ids[j])]
        for k in (i, j):
            if k not in sel and len(sel) < MAX_DRIVERS:
                sel.append(k)
    sel = sel[:MAX_DRIVERS]
    names = tuple(ids[k] for k in sel)
    return Design(drivers=names, columns=names, products=tuple(prods), loadings={})

